<script setup lang="ts">
import { useGameStore } from '../stores/game'
const store=useGameStore();const items=[{id:'first-win',name:'初次中奖',desc:'累计中奖 1 次',goal:1,reward:100,progress:()=>store.game.statistics.totalWon},{id:'lucky-star',name:'幸运新星',desc:'累计中奖 10 次',goal:10,reward:500,progress:()=>store.game.statistics.totalWon},{id:'scratch-master',name:'刮奖达人',desc:'累计刮奖 100 次',goal:100,reward:1000,progress:()=>store.game.statistics.totalScratched},{id:'tycoon',name:'彩票大亨',desc:'累计获得 100,000 金币',goal:100000,reward:5000,progress:()=>store.game.statistics.totalEarned},{id:'777',name:'777 收藏家',desc:'获得一次幸运 777 彩票',goal:1,reward:2000,progress:()=>store.game.tickets.some(t=>t.gameId==='lucky777'&&t.isWinner)?1:0},{id:'automation',name:'自动化大师',desc:'自动化天赋达到 Lv.8',goal:8,reward:10000,progress:()=>store.game.talents.automation}]
function claim(item:typeof items[number]){if(item.progress()<item.goal||store.game.achievements[item.id]?.claimed)return;store.claimAchievement(item.id,item.reward,`成就奖励：${item.name}`)}
</script>
<template><view class="page"><view class="page-heading"><view><text class="eyebrow">MILESTONES & RECORDS</text><text>成就与经营统计</text><view>每一次刮奖、每一次成长，都值得被记录。</view></view></view><view class="stats-grid"><view class="panel record-stat"><text>累计刮奖</text><text>{{store.game.statistics.totalScratched}}</text></view><view class="panel record-stat"><text>累计中奖</text><text>{{store.game.statistics.totalWon}}</text></view><view class="panel record-stat"><text>累计收入</text><text>{{store.game.statistics.totalEarned.toLocaleString()}}</text></view><view class="panel record-stat"><text>累计支出</text><text>{{store.game.statistics.totalSpent.toLocaleString()}}</text></view></view><view class="achievement-list"><view v-for="item in items" :key="item.id" class="panel achievement"><text class="achievement-icon">🏅</text><view class="achievement-info"><text>{{item.name}}</text><text>{{item.desc}}</text><view class="progress-line"><text :style="{width:`${Math.min(100,item.progress()/item.goal*100)}%`}"/></view></view><view class="achievement-action"><text>+{{item.reward.toLocaleString()}} 🪙</text><button class="btn" :class="item.progress()>=item.goal?'primary':'secondary'" :disabled="item.progress()<item.goal||store.game.achievements[item.id]?.claimed" @tap="claim(item)">{{store.game.achievements[item.id]?.claimed?'已领取':item.progress()>=item.goal?'领取奖励':'进行中'}}</button></view></view></view><view class="panel transaction-panel"><view class="section-head"><text>最近交易记录</text><text class="muted">最多保留 100 条</text></view><view v-for="tx in store.game.transactions.slice(0,8)" :key="tx.id" class="transaction"><text>{{tx.reason}}</text><text>{{new Date(tx.createdAt).toLocaleString()}}</text><text :class="tx.type">{{tx.type==='income'?'+':'-'}}{{tx.amount.toLocaleString()}}</text></view><view v-if="!store.game.transactions.length" class="empty">还没有交易记录</view></view></view></template>